sys_variable_value.value:
(function() {
    var gr = new GlideRecord('sc_req_item');
    gr.addQuery('cat_item.name', 'Equipment Loadout');
    gr.orderByDesc('sys_created_on');
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
        var assignmentGroup = gr.getDisplayValue('assignment_group');
        gs.info('Assignment Group: ' + assignmentGroup);
        
        assertEqual({
            name: 'Auto Assignment Check — Equipment should go to IT Hardware',
            expected: 'IT Hardware',
            actual: assignmentGroup
        });
    } else {
        fail('No Equipment Loadout request found in sc_req_item');
    }
})();
